import React, { useRef, useEffect, useState } from 'react';
import { ParameterDefinition, EFFECTS_LIBRARY } from '../modules/effects';
import { EffectTheme } from '../modules/themes';
import { engine, uiBridge } from '../engine/ThreeEngine';

export const ColorInput = ({ effectId, paramDef, theme }: { effectId: string, paramDef: ParameterDefinition, theme: EffectTheme }) => {
  const [color, setColor] = useState<string>(paramDef.default as string);
  const [isDisabled, setIsDisabled] = useState(() => {
    if (!paramDef.dependsOn) return false;
    const depParam = EFFECTS_LIBRARY.find(e => e.id === effectId)?.parameters.find(p => p.id === paramDef.dependsOn);
    if (!depParam) return false;
    let currentVal = depParam.default;
    if (engine) {
        const pass = engine.scenes.find(s => s.id === effectId);
        if (pass && pass.material.uniforms[paramDef.dependsOn]) {
            currentVal = pass.material.uniforms[paramDef.dependsOn].value;
        }
    }
    return !Boolean(currentVal);
  });

  useEffect(() => {
    const bindingKey = `${effectId}_${paramDef.id}`;
    const handler = (val: string) => {
      setColor(val);
    };
    uiBridge.on(bindingKey, handler);

    let depHandler: ((val: any) => void) | null = null;
    let depKey = '';

    if (paramDef.dependsOn) {
      depKey = `${effectId}_${paramDef.dependsOn}`;
      depHandler = (val: any) => {
        setIsDisabled(!Boolean(val));
      };
      uiBridge.on(depKey, depHandler);
    }

    // Cleanup
    return () => {
       const listeners = uiBridge.listeners[bindingKey];
       if (listeners) {
         uiBridge.listeners[bindingKey] = listeners.filter(l => l !== handler);
       }
       if (depKey && depHandler) {
         const depListeners = uiBridge.listeners[depKey];
         if (depListeners) {
           uiBridge.listeners[depKey] = depListeners.filter(l => l !== depHandler);
         }
       }
    }
  }, [effectId, paramDef]);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (isDisabled) return;
    const newVal = e.target.value;
    setColor(newVal);

    if (engine) {
      engine.setParameter(effectId, paramDef.id, newVal);
    }
  };

  const themeData = theme.colorInput;

  return (
    <div className={`relative w-16 h-16 rounded-full border-2 ${themeData.border} ${themeData.bg} shadow-[inset_0_5px_8px_rgba(0,0,0,0.8),0_1px_1px_rgba(255,255,255,0.05)] flex items-center justify-center transition-opacity ${isDisabled ? 'opacity-30 cursor-not-allowed' : ''}`}>
      {/* Textured outer ring */}
      <div className={`absolute inset-1 rounded-full border ${themeData.ringBorder} ${themeData.ringBg} pointer-events-none`} />

      {/* Inner lens */}
      <div 
        className="relative w-10 h-10 rounded-full shadow-[inset_0_2px_4px_rgba(255,255,255,0.4),inset_0_-2px_4px_rgba(0,0,0,0.4)] pointer-events-none z-10 transition-colors duration-75"
        style={{ 
          backgroundColor: color, 
          boxShadow: `inset 0 1px 3px rgba(255,255,255,0.4), inset 0 -2px 4px rgba(0,0,0,0.4), 0 0 10px ${color}88`
        }}
      >
        {/* Glossy overlay on lens */}
        <div className="absolute inset-0 rounded-full bg-gradient-to-b from-white/30 to-transparent pointer-events-none" />
      </div>

      {/* Invisible actual input */}
      <input 
        type="color" 
        value={color}
        disabled={isDisabled}
        onChange={handleChange}
        onInput={handleChange} 
        onClick={(e) => {
          if (isDisabled) {
             e.preventDefault();
             return;
          }
          if (e.altKey || e.metaKey) {
            e.preventDefault();
            const defaultColor = paramDef.default as string;
            setColor(defaultColor);
            if (engine) engine.setParameter(effectId, paramDef.id, defaultColor);
          }
        }}
        className={`absolute inset-0 w-full h-full opacity-0 z-20 ${isDisabled ? 'cursor-not-allowed pointer-events-none' : 'cursor-pointer'}`}
      />
    </div>
  );
};

import React, { useRef, useEffect, useState } from 'react';
import { ParameterDefinition, EFFECTS_LIBRARY } from '../modules/effects';
import { engine, uiBridge } from '../engine/ThreeEngine';
import { EffectTheme } from '../modules/themes';

export const Knob = ({ effectId, paramDef, index, theme }: { effectId: string, paramDef: ParameterDefinition, index: number, theme: EffectTheme }) => {
  const knobRef = useRef<HTMLDivElement>(null);
  const valueRef = useRef<number>(paramDef.default as number);
  const isDragging = useRef(false);
  const startY = useRef(0);
  const startVal = useRef(0);
  const [isDisabled, setIsDisabled] = useState(() => {
    if (!paramDef.dependsOn) return false;
    const depParam = EFFECTS_LIBRARY.find(e => e.id === effectId)?.parameters.find(p => p.id === paramDef.dependsOn);
    if (!depParam) return false;
    let currentVal = depParam.default;
    if (engine) {
        const pass = engine.scenes.find(s => s.id === effectId);
        if (pass && pass.material.uniforms[paramDef.dependsOn]) {
            currentVal = pass.material.uniforms[paramDef.dependsOn].value;
        }
    }
    return !Boolean(currentVal);
  });

  const min = paramDef.min || 0;
  const max = paramDef.max || 1;

  const themeData = theme.knob;

  const updateVisuals = (val: number) => {
    if (!knobRef.current) return;
    const pct = (val - min) / (max - min);
    // design seems to rotate starting point slightly differently, but mapping is the same concept
    const angle = -135 + (pct * 270);
    knobRef.current.style.transform = `rotate(${angle}deg)`;
  };

  useEffect(() => {
    updateVisuals(valueRef.current);

    const bindingKey = `${effectId}_${paramDef.id}`;

    const handler = (val: number) => {
      if (isDragging.current) return;
      valueRef.current = val;
      updateVisuals(val);
    };

    uiBridge.on(bindingKey, handler);

    if (paramDef.dependsOn) {
      const depKey = `${effectId}_${paramDef.dependsOn}`;
      const depHandler = (val: any) => {
        setIsDisabled(!Boolean(val));
      };
      uiBridge.on(depKey, depHandler);
      return () => {
         // handle cleanup if necessary for uiBridge, but it's not currently implemented as returning off
      };
    }
  }, [effectId, paramDef]);

  const handlePointerDown = (e: React.PointerEvent) => {
    if (isDisabled) return;
    if (e.altKey || e.metaKey) {
      handleDoubleClick();
      return;
    }
    isDragging.current = true;
    e.currentTarget.setPointerCapture(e.pointerId);
    startY.current = e.clientY;
    startVal.current = valueRef.current;
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (isDisabled || !isDragging.current) return;
    const deltaY = startY.current - e.clientY;

    const sensitivity = e.shiftKey ? 0.001 : 0.01;
    let newVal = startVal.current + (deltaY * sensitivity * (max - min));
    newVal = Math.max(min, Math.min(newVal, max));

    valueRef.current = newVal;
    updateVisuals(newVal);

    if (engine) {
      engine.setParameter(effectId, paramDef.id, newVal);
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (isDisabled) return;
    isDragging.current = false;
    e.currentTarget.releasePointerCapture(e.pointerId);
  };

  const handleDoubleClick = () => {
    if (isDisabled) return;
    const defaultVal = paramDef.default as number;
    valueRef.current = defaultVal;
    updateVisuals(defaultVal);
    if (engine) engine.setParameter(effectId, paramDef.id, defaultVal);
  };

  return (
    <div className={`relative w-16 h-16 rounded-full ${themeData.outerBg} border-2 ${themeData.outerBorder} shadow-[inset_0_4px_10px_rgba(0,0,0,0.8),0_5px_10px_rgba(0,0,0,0.4),0_1px_0_rgba(255,255,255,0.05)] flex items-center justify-center select-none touch-none transition-opacity ${isDisabled ? 'opacity-30 cursor-not-allowed' : 'cursor-pointer'}`}
         onPointerDown={handlePointerDown}
         onPointerMove={handlePointerMove}
         onPointerUp={handlePointerUp}
         onDoubleClick={handleDoubleClick}
    >
      <div className={`absolute w-12 h-12 rounded-full bg-gradient-to-br ${themeData.innerGrad} shadow-[0_4px_8px_rgba(0,0,0,0.6),0_8px_16px_rgba(0,0,0,0.4),inset_0_1px_1px_rgba(255,255,255,0.1)]`}></div>
      <div 
        ref={knobRef}
        className={`absolute w-12 h-12 rounded-full flex items-center justify-center`}
      >
        <div className="w-1 h-4 rounded-full mb-6" style={{ backgroundColor: themeData.accentColor }}></div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from "react";
import { Play, Pause, Image as ImageIcon, Film } from "lucide-react";
import { initEngine, engine, uiBridge } from "../engine/ThreeEngine";
import { EFFECTS_LIBRARY } from "../modules/effects";
import { Flow } from "flow-sdk";

export const Monitor = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const imageRef = useRef<HTMLImageElement>(null);

  const [isPlaying, setIsPlaying] = useState(false);
  const [hasMedia, setHasMedia] = useState(false);
  const [isVideo, setIsVideo] = useState(true);
  const [isExporting, setIsExporting] = useState(false);
  const [isCapturing, setIsCapturing] = useState(false);
  const [activeAutomations, setActiveAutomations] = useState<
    { effectId: string; paramId: string }[]
  >([]);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [error, setError] = useState<string | null>(null);

  // Keep a reference to the raw media data for export
  const mediaDataRef = useRef<{ base64: string; mimeType: string; name: string } | null>(null);

  useEffect(() => {
    if (canvasRef.current) {
      initEngine(canvasRef.current);
    }
  }, []);

  useEffect(() => {
    let animationFrameId: number;
    const updateTime = () => {
      if (isVideo && videoRef.current && !videoRef.current.paused) {
        setCurrentTime(videoRef.current.currentTime);
      }
      animationFrameId = requestAnimationFrame(updateTime);
    };
    animationFrameId = requestAnimationFrame(updateTime);
    return () => cancelAnimationFrame(animationFrameId);
  }, [isVideo]);

  useEffect(() => {
    const interval = setInterval(() => {
      if (engine) {
        const newAutos: { effectId: string; paramId: string }[] = [];
        for (const effectId in engine.automationStore) {
          for (const paramId in engine.automationStore[effectId]) {
            if (engine.automationStore[effectId][paramId].length > 0) {
              newAutos.push({ effectId, paramId });
            }
          }
        }
        setActiveAutomations((prev) => {
          if (prev.length !== newAutos.length) return newAutos;
          for (let i = 0; i < prev.length; i++) {
            if (
              prev[i].effectId !== newAutos[i].effectId ||
              prev[i].paramId !== newAutos[i].paramId
            )
              return newAutos;
          }
          return prev;
        });
      }
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const handleMediaSelect = async () => {
    setError(null);
    try {
      const media = await Flow.media.select({ filter: "all" });
      if (!media || !canvasRef.current || !engine) return;

      mediaDataRef.current = { 
        base64: media.base64, 
        mimeType: media.mimeType, 
        name: media.name 
      };

      const isMediaVideo = media.type === "video";
      setIsVideo(isMediaVideo);

      // Convert base64 to Blob URL for performance
      const bytes = Uint8Array.from(atob(media.base64), (c) => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: media.mimeType });
      const url = URL.createObjectURL(blob);

      if (isMediaVideo && videoRef.current) {
        videoRef.current.src = url;
        videoRef.current.play();
        setIsPlaying(true);
      } else if (!isMediaVideo && imageRef.current) {
        if (videoRef.current) videoRef.current.pause();
        imageRef.current.src = url;
        setIsPlaying(false);
        setDuration(0);
        setCurrentTime(0);
        // Clear automations when switching to image
        engine.automationStore = {};
        setActiveAutomations([]);
      }
      setHasMedia(true);
      uiBridge.emit('mediaStatusChanged', { hasMedia: true, isVideo: isMediaVideo });
    } catch (err) {
      if (err instanceof Error && err.message.includes("cancel")) return;
      setError(err instanceof Error ? err.message : "Failed to load media");
    }
  };

  const togglePlay = () => {
    if (!videoRef.current || !isVideo) return;
    if (isPlaying) {
      videoRef.current.pause();
    } else {
      videoRef.current.play();
    }
    setIsPlaying(!isPlaying);
  };

  const handleExport = async () => {
    if (!mediaDataRef.current) return;

    setError(null);
    setIsExporting(true);

    if (!isVideo) {
      try {
        await handleCaptureFrame();
      } finally {
        setIsExporting(false);
      }
      return;
    }

    try {
      // Reconstruct File-like object for mediabunny
      const bytes = Uint8Array.from(atob(mediaDataRef.current.base64), (c) => c.charCodeAt(0));
      const file = new File([bytes], mediaDataRef.current.name, { type: mediaDataRef.current.mimeType });

      const { exportMedia } = await import("../engine/Export");
      await exportMedia(file, () => {});
    } catch (err) {
      setError(err instanceof Error ? err.message : "Export failed");
    } finally {
      setIsExporting(false);
    }
  };

  const handleCaptureFrame = async () => {
    if (!canvasRef.current) return;

    // Pause playback if capturing
    if (isPlaying && isVideo && videoRef.current) {
      videoRef.current.pause();
      setIsPlaying(false);
    }

    setError(null);
    setIsCapturing(true);
    try {
      const dataUrl = canvasRef.current.toDataURL("image/png");
      const base64 = dataUrl.split(",")[1];
      const name = `pixelBento-capture`;

      await Flow.save({
        base64,
        mimeType: "image/png",
        name
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to save capture");
    } finally {
      setIsCapturing(false);
    }
  };

  const removeAutomation = (effectId: string, paramId: string) => {
    if (engine && engine.automationStore[effectId]) {
      engine.automationStore[effectId][paramId] = [];
    }
  };

  const formatTime = (timeInSeconds: number) => {
    const m = Math.floor(timeInSeconds / 60);
    const s = Math.floor(timeInSeconds % 60);
    return `${m.toString().padStart(2, "0")}:${s.toString().padStart(2, "0")}`;
  };

  const handleSeekStart = (e: React.PointerEvent<HTMLDivElement>) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    handleSeek(e);
  };
  const handleSeekMove = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.buttons === 1) handleSeek(e);
  };
  const handleSeek = (
    e: React.MouseEvent<HTMLDivElement> | React.PointerEvent<HTMLDivElement>,
  ) => {
    if (!videoRef.current || Math.floor(duration) === 0 || !isVideo) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pos = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    videoRef.current.currentTime = pos * duration;
    setCurrentTime(pos * duration);
    if (videoRef.current.paused && engine?.videoTexture) {
      engine.videoTexture.needsUpdate = true;
    }
  };

  const progressPercent = duration > 0 ? (currentTime / duration) * 100 : 0;
  const timeStr = formatTime(currentTime);

  return (
    <div className="flex-grow flex flex-col h-full bg-[#080808]">
      <div className="flex items-center justify-between p-3 border-b border-[#222] shrink-0">
        <span className="text-[11px] text-[#555] uppercase tracking-widest font-bold">
          Monitor
        </span>
        {hasMedia && (
          <button 
            onClick={handleMediaSelect}
            className="px-4 h-8 border border-[#333] rounded text-[10px] font-bold uppercase tracking-widest transition-colors bg-[#222] text-[#e0e0e0] hover:bg-[#2a2a2a] flex items-center justify-center cursor-pointer"
          >
            Replace Media
          </button>
        )}
      </div>

      <div className="p-4 flex-grow flex flex-col min-h-0">
        {error && (
          <div className="mb-4 p-2 bg-red-500/10 border border-red-500/20 text-red-400 text-[10px] uppercase tracking-widest rounded text-center">
            {error}
          </div>
        )}

        <div className="relative bg-[#000] w-full min-h-[250px] flex-1 rounded-sm shadow-[inset_0_0_100px_rgba(0,0,0,0.8)] border border-[#1a1a1a] flex items-center justify-center overflow-hidden">
          <div className="absolute inset-0 bg-gradient-to-b from-transparent via-white/[0.02] to-white/[0.01] pointer-events-none z-10"></div>

          {!hasMedia && (
            <div className="absolute inset-0 flex items-center justify-center z-20">
              <button 
                onClick={handleMediaSelect}
                className="hover:opacity-100 opacity-80 transition-opacity flex flex-col items-center justify-center gap-4 text-[#bbb] hover:text-white group cursor-pointer bg-transparent border-none"
              >
                <div className="flex items-center gap-4">
                  <ImageIcon size={32} strokeWidth={1.5} />
                  <Film size={32} strokeWidth={1.5} />
                </div>
                <div className="text-[10px] uppercase tracking-[0.2em] font-bold">
                  Load Media
                </div>
              </button>
            </div>
          )}

          <video
            ref={videoRef}
            className="hidden"
            loop
            crossOrigin="anonymous"
            playsInline
            muted
            onLoadedMetadata={() => {
              if (videoRef.current && isVideo) {
                setDuration(videoRef.current.duration);
                engine?.setSource(
                  videoRef.current,
                  videoRef.current.videoWidth,
                  videoRef.current.videoHeight,
                  true,
                );
              }
            }}
          />

          <img
            ref={imageRef}
            className="hidden"
            crossOrigin="anonymous"
            onLoad={() => {
              if (imageRef.current && !isVideo) {
                engine?.setSource(
                  imageRef.current,
                  imageRef.current.naturalWidth,
                  imageRef.current.naturalHeight,
                  false,
                );
              }
            }}
          />

          <canvas
            ref={canvasRef}
            className="max-w-full max-h-full object-contain pointer-events-none"
          />
        </div>

        {/* Playback Controls */}
        <div className="mt-4 bg-[#111] p-3 rounded border border-[#222] shadow-xl shrink-0">
          <div
            className="h-1 bg-[#222] w-full mb-3 relative cursor-pointer group touch-none"
            onPointerDown={handleSeekStart}
            onPointerMove={handleSeekMove}
          >
            <div
              className="absolute left-0 top-0 h-full bg-white"
              style={{ width: `${progressPercent}%`, pointerEvents: "none" }}
            ></div>
            <div
              className="absolute top-1/2 -translate-y-1/2 w-3 h-3 bg-white rounded-full shadow-md opacity-0 group-hover:opacity-100 transition-opacity"
              style={{
                left: `calc(${progressPercent}% - 6px)`,
                pointerEvents: "none",
              }}
            ></div>
          </div>
          <div className="flex items-center justify-between relative">
            <div className="flex gap-2 relative z-10 w-1/3">
              <button
                onClick={togglePlay}
                disabled={!hasMedia || !isVideo}
                className="w-12 h-8 bg-white border border-white rounded shadow-lg flex items-center justify-center text-black hover:brightness-110 active:brightness-90 cursor-pointer disabled:opacity-50 disabled:grayscale disabled:cursor-not-allowed"
              >
                {isPlaying ? (
                  <Pause size={16} fill="currentColor" />
                ) : (
                  <Play size={16} fill="currentColor" />
                )}
              </button>
            </div>
            <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 font-mono text-xl tracking-tighter text-white pointer-events-none w-max text-center">
              {timeStr}
            </div>
            <div className="flex gap-2 relative z-10 w-1/3 justify-end whitespace-nowrap">
              {isVideo && (
                <button
                  onClick={handleCaptureFrame}
                  disabled={!hasMedia || isCapturing}
                  className="px-4 h-8 border border-[#333] rounded text-[10px] font-bold uppercase tracking-widest transition-colors bg-[#222] text-[#e0e0e0] cursor-pointer hover:bg-[#2a2a2a] disabled:opacity-50 disabled:grayscale disabled:cursor-not-allowed flex items-center justify-center gap-2 min-w-[110px]"
                >
                  {isCapturing ? (
                    <>
                      <div className="w-2 h-2 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                      <span>Capturing...</span>
                    </>
                  ) : (
                    "Capture Frame"
                  )}
                </button>
              )}
              <button
                onClick={handleExport}
                disabled={!hasMedia || isExporting}
                className="px-4 h-8 bg-white text-black text-[10px] font-bold uppercase tracking-widest rounded hover:brightness-110 disabled:opacity-50 disabled:grayscale transition-all cursor-pointer disabled:cursor-not-allowed flex items-center justify-center gap-2 min-w-[90px]"
              >
                {isExporting ? (
                  <>
                    <div className="w-2 h-2 border-2 border-black/20 border-t-black rounded-full animate-spin" />
                    <span>Exporting...</span>
                  </>
                ) : (
                  "Export"
                )}
              </button>
            </div>
          </div>
        </div>

        <div className="mt-6 shrink-0 h-32 overflow-y-auto custom-scrollbar">
          <h3 className="text-[11px] uppercase tracking-widest text-[#555] font-bold mb-3 border-b border-[#222] pb-1 sticky top-0 bg-[#080808] z-10">
            Active Automations
          </h3>
          <div className="space-y-1">
            {activeAutomations.length === 0 && (
              <div className="text-[9px] font-mono text-[#444] opacity-50 p-2">
                NO ACTIVE AUTOMATION
              </div>
            )}
            {activeAutomations.map((auto) => {
              const effect = EFFECTS_LIBRARY.find(
                (e) => e.id === auto.effectId,
              );
              const param = effect?.parameters.find(
                (p) => p.id === auto.paramId,
              );
              return (
                <div
                  key={`${auto.effectId}-${auto.paramId}`}
                  className="flex justify-between items-center bg-[#0d0d0d] p-2 border border-[#1a1a1a] rounded"
                >
                  <span className="text-[11px] font-mono">
                    <span className="text-white mr-2">●</span>
                    {effect?.name.split(" ")[0]} : {param?.name}
                  </span>
                  <button
                    onClick={() =>
                      removeAutomation(auto.effectId, auto.paramId)
                    }
                    className="text-[9px] text-[#444] hover:text-white cursor-pointer"
                  >
                    [ REMOVE ]
                  </button>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from "react";
import { EFFECTS_LIBRARY } from "../modules/effects";
import { RackModule } from "./RackModule";
import { engine, uiBridge } from "../engine/ThreeEngine";

export const Rack = () => {
  const [isRecording, setIsRecording] = useState(false);
  const [globalEnabled, setGlobalEnabled] = useState(true);
  const [globalMix, setGlobalMix] = useState(1.0);
  const [hasMedia, setHasMedia] = useState(false);
  const [isVideo, setIsVideo] = useState(true);

  useEffect(() => {
    if (engine) {
      engine.isRecording = isRecording;
    }
  }, [isRecording]);

  useEffect(() => {
    if (engine) {
      engine.setGlobalEnabled(globalEnabled);
    }
  }, [globalEnabled]);

  useEffect(() => {
    if (engine) {
      engine.setGlobalMix(globalMix);
    }
  }, [globalMix]);

  useEffect(() => {
    const handler = (status: { hasMedia: boolean; isVideo: boolean }) => {
      setHasMedia(status.hasMedia);
      setIsVideo(status.isVideo);
      if (!status.isVideo) {
        setIsRecording(false);
      }
    };
    uiBridge.on('mediaStatusChanged', handler);

    // Initial sync with engine if it's already initialized
    if (engine && engine.mediaElement) {
      setHasMedia(true);
      setIsVideo(engine.isVideo);
    }

    return () => {
      if (uiBridge.listeners['mediaStatusChanged']) {
