import React, { useState } from 'react';
import { RotateCcw } from 'lucide-react';
import { EffectDefinition } from '../modules/effects';
import { Knob } from './Knob';
import { Switch } from './Switch';
import { ColorInput } from './ColorInput';
import { engine, uiBridge } from '../engine/ThreeEngine';

export const RackModule = ({ effect, index }: { effect: EffectDefinition, index: number, key?: React.Key }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [isPowered, setIsPowered] = useState(false);

  const applyPreset = (presetValues: Record<string, number | boolean | string>) => {
    Object.keys(presetValues).forEach(paramId => {
      const val = presetValues[paramId];
      if (engine) engine.setParameter(effect.id, paramId, typeof val === 'boolean' ? (val ? 1:0) : val);
      uiBridge.emit(`${effect.id}_${paramId}`, val);
    });
  };

  const togglePower = (e: React.MouseEvent) => {
    e.stopPropagation();
    const nextVal = !isPowered;
    setIsPowered(nextVal);
    if (engine) engine.setPassEnabled(effect.id, nextVal);
  };

  const resetToDefault = (e: React.MouseEvent) => {
    e.stopPropagation();
    const defaultValues: Record<string, number | boolean | string> = {};
    effect.parameters.forEach(param => {
      defaultValues[param.id] = param.default;
    });
    applyPreset(defaultValues);
  };

  const themeData = effect.theme.module;

  const screwAngles = React.useMemo(() => [
    Math.random() * 360,
    Math.random() * 360,
    Math.random() * 360,
    Math.random() * 360
  ], []);

  return (
    <div 
      className={`w-full ${themeData.bg} border-b-2 ${themeData.border} p-6 relative shadow-2xl flex-shrink-0`}
    >
      <div className={`absolute top-2 left-2 w-3 h-3 ${themeData.screwRing} rounded-full border flex items-center justify-center`}><div className={`w-2 h-[1px] ${themeData.screwLine}`} style={{ transform: `rotate(${screwAngles[0]}deg)` }}></div></div>
      <div className={`absolute top-2 right-2 w-3 h-3 ${themeData.screwRing} rounded-full border flex items-center justify-center`}><div className={`w-2 h-[1px] ${themeData.screwLine}`} style={{ transform: `rotate(${screwAngles[1]}deg)` }}></div></div>
      <div className={`absolute bottom-2 left-2 w-3 h-3 ${themeData.screwRing} rounded-full border flex items-center justify-center`}><div className={`w-2 h-[1px] ${themeData.screwLine}`} style={{ transform: `rotate(${screwAngles[2]}deg)` }}></div></div>
      <div className={`absolute bottom-2 right-2 w-3 h-3 ${themeData.screwRing} rounded-full border flex items-center justify-center`}><div className={`w-2 h-[1px] ${themeData.screwLine}`} style={{ transform: `rotate(${screwAngles[3]}deg)` }}></div></div>

      <div className="flex justify-between items-center mb-2">
        <div className="flex gap-4 items-center">
          <div 
            onClick={togglePower} 
            className={`w-8 h-4 rounded-full p-0.5 cursor-pointer flex items-center transition-colors border ${themeData.border} ${isPowered ? themeData.switchBgActive : themeData.switchBg}`}
          >
            <div 
              className={`w-3 h-3 rounded-full transition-all z-10 ${isPowered ? 'translate-x-4 ' + themeData.accentShadow : 'translate-x-0 bg-[#333]'}`} 
              style={{ backgroundColor: isPowered ? themeData.accent : undefined }}
            />
          </div>
          <h2 
            className={`text-2xl md:text-3xl font-black italic uppercase tracking-tighter leading-none transition-opacity cursor-pointer hover:opacity-80 ${themeData.header} ${!isPowered ? 'opacity-30' : ''}`}
            onClick={() => setIsExpanded(!isExpanded)}
          >
            {effect.name}
          </h2>
        </div>
        <div className="flex items-center gap-1">
          <button 
            onClick={resetToDefault}
            className={`p-2 ${themeData.btn} transition-colors cursor-pointer hover:opacity-80`}
            title="Reset to Default"
          >
            <RotateCcw size={14} />
          </button>
        </div>
      </div>

      {isExpanded && (
        <div className={`mt-8 transition-opacity ${!isPowered ? 'opacity-30 pointer-events-none' : ''}`}>
           {effect.presets.length > 0 && (
            <div className="mb-8">
              <span className={`text-[10px] uppercase font-bold tracking-widest ${themeData.label} block mb-3`}>Presets</span>
              <div className="grid grid-cols-2 gap-2">
                {effect.presets.map((preset) => (
                  <button
                    key={preset.id}
                    onClick={() => applyPreset(preset.values)}
                    className={`py-3 px-4 ${themeData.presetBg} border ${themeData.presetBorder} font-bold uppercase text-xs transition-colors ${themeData.presetHover} ${themeData.presetText}`}
                  >
                    {preset.name}
                  </button>
                ))}
              </div>
            </div>
           )}

           <div className="flex flex-wrap justify-center gap-y-8 gap-x-12">
              {effect.parameters.filter(p => !p.hidden).map((param, i) => (
                <div key={param.id} className="flex flex-col items-center gap-2">
                  {param.type === 'float' ? (
                    <Knob effectId={effect.id} paramDef={param} index={i} theme={effect.theme} />
                  ) : param.type === 'color' ? (
                    <ColorInput effectId={effect.id} paramDef={param} theme={effect.theme} />
                  ) : (
                    <Switch effectId={effect.id} paramDef={param} theme={effect.theme} />
                  )}
                  <span className={`text-[10px] uppercase font-bold tracking-widest ${themeData.label} text-center`}>{param.name}</span>
                </div>
              ))}
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useRef, useEffect } from 'react';
import { ParameterDefinition } from '../modules/effects';
import { engine, uiBridge } from '../engine/ThreeEngine';
import { EffectTheme } from '../modules/themes';

export const Switch = ({ effectId, paramDef, theme }: { effectId: string, paramDef: ParameterDefinition, theme: EffectTheme }) => {
  const switchRef = useRef<HTMLDivElement>(null);
  const valueRef = useRef<boolean>(paramDef.default as boolean);
  const themeData = theme.switch;

  const updateVisuals = (val: boolean) => {
    if (!switchRef.current) return;
    if (val) {
      switchRef.current.style.transform = 'translateY(-12px)';
      switchRef.current.style.boxShadow = `0 0 12px 2px ${themeData.accentColor}`;
      switchRef.current.style.backgroundColor = themeData.accentColor;
    } else {
      switchRef.current.style.transform = 'translateY(12px)';
      switchRef.current.style.boxShadow = 'inset 0 1px 3px rgba(0,0,0,0.8)';
      switchRef.current.style.backgroundColor = themeData.switchBaseHex;
    }
  };

  useEffect(() => {
    updateVisuals(valueRef.current);

    const bindingKey = `${effectId}_${paramDef.id}`;
    const handler = (val: any) => {
      const boolVal = Boolean(val);
      valueRef.current = boolVal;
      updateVisuals(boolVal);
    };
    uiBridge.on(bindingKey, handler);
  }, []);

  const toggle = (e: React.MouseEvent) => {
    if (e.altKey || e.metaKey) {
      const defaultVal = paramDef.default as boolean;
      valueRef.current = defaultVal;
      updateVisuals(defaultVal);
      if (engine) engine.setParameter(effectId, paramDef.id, defaultVal ? 1.0 : 0.0);
      return;
    }
    const newVal = !valueRef.current;
    valueRef.current = newVal;
    updateVisuals(newVal);

    if (engine) {
      engine.setParameter(effectId, paramDef.id, newVal ? 1.0 : 0.0);
    }
  };

  return (
    <div 
      className={`relative w-16 h-16 rounded-full border-2 ${themeData.border} ${themeData.bg} shadow-[inset_0_4px_10px_rgba(0,0,0,0.8),0_1px_0_rgba(255,255,255,0.05)] flex items-center justify-center cursor-pointer select-none touch-none`}
      onClick={toggle}
    >
      <div className={`w-6 h-10 ${themeData.innerBg} rounded border border-black/50 ${themeData.innerShadow} flex items-center justify-center overflow-hidden`}>
        <div 
          ref={switchRef}
          className="w-5 h-1.5 rounded-sm transition-all duration-100 z-10"
        ></div>
      </div>
    </div>
  );
};

