import { engine } from './ThreeEngine';
import { Conversion, Input, Output, Mp4OutputFormat, BufferTarget, BlobSource, ALL_FORMATS, QUALITY_VERY_HIGH } from 'mediabunny';
import * as THREE from 'three';

export const exportMedia = async (file: File, onProgress: (p: number) => void) => {
  if (!engine || !engine.mediaElement) return;

  const bufferTarget = new BufferTarget();
  const exportCanvas = document.createElement('canvas');
  const exportCtx = exportCanvas.getContext('2d');

  const conversion = await Conversion.init({
    input: new Input({ formats: ALL_FORMATS, source: new BlobSource(file) }),
    output: new Output({
        format: new Mp4OutputFormat({ fastStart: 'fragmented' }),
        target: bufferTarget,
    }),
    video: {
        codec: 'avc',
        bitrate: 20_000_000,              
        process: (sample: any) => {
            // Update texture
            if (sample.toCanvasImageSource && exportCtx) {
               const imageSource = typeof sample.toCanvasImageSource === 'function' ? sample.toCanvasImageSource() : (sample.videoFrame || sample);

               const width = imageSource.displayWidth || imageSource.width || (engine.mediaElement as HTMLVideoElement).videoWidth;
               const height = imageSource.displayHeight || imageSource.height || (engine.mediaElement as HTMLVideoElement).videoHeight;

               if (!engine.exportTexture) {
                   exportCanvas.width = width;
                   exportCanvas.height = height;
                   engine.exportTexture = new THREE.CanvasTexture(exportCanvas);
                   engine.exportTexture.minFilter = engine.videoTexture!.minFilter;
                   engine.exportTexture.magFilter = engine.videoTexture!.magFilter;
               } else if (exportCanvas.width !== width || exportCanvas.height !== height) {
                   exportCanvas.width = width;
                   exportCanvas.height = height;
               }

               exportCtx.clearRect(0, 0, width, height);
               exportCtx.drawImage(imageSource, 0, 0, width, height);

               engine.exportTexture.needsUpdate = true;

               // Sync Time
               // mediabunny timestamps are in seconds
               const time = typeof sample.microsecondTimestamp !== 'undefined' ? sample.microsecondTimestamp / 1e6 : (sample.timestamp > 10000 ? sample.timestamp / 1e6 : sample.timestamp);

               // Apply automation synchronously
               engine.applyAutomation(time);

               // Render
               engine.renderPasses(time);
            }

            if (sample && typeof sample.close === 'function') {
                sample.close();
            }
            return engine.renderer.domElement;
        }
    },
    audio: {
        bitrate: QUALITY_VERY_HIGH        
    }
  });

  conversion.onProgress = onProgress;

  engine.isExporting = true;
  try {
    await conversion.execute();
  } finally {
    engine.isExporting = false;
    if (engine.exportTexture) {
      engine.exportTexture.dispose();
      engine.exportTexture = null;
    }
  }

  const buffer = bufferTarget.buffer;
  if (!buffer) return;

  // Convert ArrayBuffer to Base64 for Flow.save
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (let i = 0; i < bytes.byteLength; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  const base64 = btoa(binary);

  const { Flow } = await import("flow-sdk");
  await Flow.save({ 
    base64, 
    mimeType: 'video/mp4', 
    name: 'pixelBento-export' 
  });
};

import * as THREE from 'three';
import { EFFECTS_LIBRARY, defaultVertexShader } from '../modules/effects';

  export type Keyframe = { time: number; value: number | boolean | string };

class UIBridge {
  listeners: Record<string, ((val: any) => void)[]> = {};

  on(event: string, callback: (val: any) => void) {
    if (!this.listeners[event]) this.listeners[event] = [];
    this.listeners[event].push(callback);
  }

  emit(event: string, val: any) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(cb => cb(val));
    }
  }
}

export const uiBridge = new UIBridge();

export class ThreeRenderer {
  renderer: THREE.WebGLRenderer;
  camera: THREE.OrthographicCamera;
  scenes: { scene: THREE.Scene, camera: THREE.OrthographicCamera, material: THREE.ShaderMaterial, renderTarget: THREE.WebGLRenderTarget, id: string, enabled: boolean }[] = [];

  finalScene: THREE.Scene;
  finalMaterial: THREE.ShaderMaterial;

  videoTexture: THREE.VideoTexture | THREE.Texture | null = null;
  mediaElement: HTMLVideoElement | HTMLImageElement | null = null;
  isVideo: boolean = true;

  width = 1920;
  height = 1080;

  automationStore: Record<string, Record<string, Keyframe[]>> = {};
  isRecording = false;
  isExporting = false;
  exportTexture: THREE.Texture | null = null;

  // DOM node styles bound to uniforms
  domBindings: Record<string, (val: number | boolean | string) => void> = {};

  constructor(canvas: HTMLCanvasElement) {
    this.renderer = new THREE.WebGLRenderer({ canvas, alpha: false, antialias: false, preserveDrawingBuffer: true });
    // Don't auto-clear because we'll render passes
    this.renderer.autoClear = false;

    this.camera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);

    this.finalScene = new THREE.Scene();
    this.finalMaterial = new THREE.ShaderMaterial({
      vertexShader: defaultVertexShader,
      fragmentShader: `
        uniform sampler2D tDiffuse;
        uniform sampler2D tOriginal;
        uniform float uMix;
        uniform float uEnabled;
        varying vec2 vUv;
        void main() {
          vec4 original = texture2D(tOriginal, vUv);
          vec4 processed = texture2D(tDiffuse, vUv);
          gl_FragColor = mix(original, processed, uMix * uEnabled);
        }
      `,
      uniforms: {
        tDiffuse: { value: null },
        tOriginal: { value: null },
        uMix: { value: 1.0 },
        uEnabled: { value: 1.0 }
      }
    });
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.finalMaterial);
    this.finalScene.add(plane);

    this.initPasses();
    this.animate = this.animate.bind(this);
    requestAnimationFrame(this.animate);
  }

  initPasses() {
    // For each effect, we create a scene + RT + material
    EFFECTS_LIBRARY.forEach((effect, index) => {
      const uniforms: any = {
        tDiffuse: { value: null },
        u_time: { value: 0 },
        u_resolution: { value: new THREE.Vector2(this.width, this.height) }
      };

      effect.parameters.forEach(param => {
        if (param.type === 'color') {
          uniforms[param.id] = { value: new THREE.Color(param.default as string) };
        } else {
          uniforms[param.id] = { value: param.default };
        }
      });

      const material = new THREE.ShaderMaterial({
        vertexShader: defaultVertexShader,
        fragmentShader: effect.shader,
        uniforms
      });

      const rt = new THREE.WebGLRenderTarget(this.width, this.height, {
        minFilter: THREE.LinearFilter,
        magFilter: THREE.LinearFilter,
        format: THREE.RGBAFormat,
      });

      const scene = new THREE.Scene();
      const plane = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), material);
      scene.add(plane);

      this.scenes.push({ scene, camera: this.camera, material, renderTarget: rt, id: effect.id, enabled: false });
    });
  }

  setPassEnabled(effectId: string, enabled: boolean) {
    const pass = this.scenes.find(s => s.id === effectId);
    if (pass) pass.enabled = enabled;
  }

  setSource(media: HTMLVideoElement | HTMLImageElement, width: number, height: number, isVideo: boolean = true) {
    this.mediaElement = media;
    this.isVideo = isVideo;

    if (this.videoTexture) {
      this.videoTexture.dispose();
    }

    if (isVideo) {
      this.videoTexture = new THREE.VideoTexture(media as HTMLVideoElement);
    } else {
      this.videoTexture = new THREE.Texture(media as HTMLImageElement);
      this.videoTexture.needsUpdate = true;
    }

    this.videoTexture.minFilter = THREE.LinearFilter;
    this.videoTexture.magFilter = THREE.LinearFilter;

    this.width = width;
    this.height = height;

    this.renderer.setSize(width, height, false);

    this.scenes.forEach(s => {
      s.renderTarget.setSize(width, height);
      if (s.material.uniforms.u_resolution) {
        s.material.uniforms.u_resolution.value.set(width, height);
      }
    });
  }

  setParameter(effectId: string, paramId: string, value: number | boolean | string, fromAutomationPlayback = false) {
    const pass = this.scenes.find(s => s.id === effectId);
    if (!pass) return;

    if (pass.material.uniforms[paramId]) {
      if (typeof value === 'string') {
        pass.material.uniforms[paramId].value.set(value);
      } else if (typeof value === 'boolean') {
        pass.material.uniforms[paramId].value = value ? 1.0 : 0.0;
      } else {
        pass.material.uniforms[paramId].value = value;
      }
    }

    if (!fromAutomationPlayback && this.isRecording && this.isVideo && this.mediaElement && !(this.mediaElement as HTMLVideoElement).paused) {
      this.recordKeyframe(effectId, paramId, (this.mediaElement as HTMLVideoElement).currentTime, value);
    }

    // Call the DOM binding if it exists
    const bindingKey = `${effectId}_${paramId}`;
    if (this.domBindings[bindingKey] && !fromAutomationPlayback) {
      this.domBindings[bindingKey](value);
    }

    if (!this.isExporting) {
      uiBridge.emit(bindingKey, value);
    }
  }

  recordKeyframe(effectId: string, paramId: string, time: number, value: number | boolean | string) {
    if (!this.automationStore[effectId]) this.automationStore[effectId] = {};
    if (!this.automationStore[effectId][paramId]) this.automationStore[effectId][paramId] = [];

    const frames = this.automationStore[effectId][paramId] as { time: number, value: number | boolean | string }[];
    // Find slot or overwrite (naive implementation for now, in real prod use binary search)
    const existing = frames.find((f: any) => Math.abs(f.time - time) < 0.05); // within 50ms overwrite
    if (existing) {
      existing.value = value;
    } else {
      frames.push({ time, value });
      frames.sort((a: any, b: any) => a.time - b.time);
    }
  }

  clearAutomation(effectId: string) {
    delete this.automationStore[effectId];
  }

  applyAutomation(time: number) {
    for (const effectId in this.automationStore) {
      for (const paramId in this.automationStore[effectId]) {
         const frames = this.automationStore[effectId][paramId];
         if (frames.length === 0) continue;

         if (frames.length === 1) {
           this.setParameter(effectId, paramId, frames[0].value, true);
           continue;
         }

         let before = frames[0];
         let after = frames[frames.length - 1];

         if (time <= before.time) {
           this.setParameter(effectId, paramId, before.value, true);
           continue;
         }

         if (time >= after.time) {
           this.setParameter(effectId, paramId, after.value, true);
           continue;
         }

         for (let i = 0; i < frames.length - 1; i++) {
           if (time >= frames[i].time && time <= frames[i+1].time) {
             before = frames[i];
             after = frames[i+1];
             break;
           }
         }

         // lerp
         if (typeof before.value === 'number' && typeof after.value === 'number') {
           const t = (time - before.time) / (after.time - before.time);
           const val = before.value + (after.value - before.value) * t;
           this.setParameter(effectId, paramId, val, true);
         } else {
           // boolean, just snap to before
           this.setParameter(effectId, paramId, before.value, true);
         }
      }
    }
  }

  setGlobalMix(mix: number) {
    this.finalMaterial.uniforms.uMix.value = mix;
  }

  setGlobalEnabled(enabled: boolean) {
    this.finalMaterial.uniforms.uEnabled.value = enabled ? 1.0 : 0.0;
  }

  renderPasses(time: number) {
    let currentTexture: THREE.Texture | null = this.exportTexture || this.videoTexture;
    if (!currentTexture) return;

    this.scenes.forEach((pass, index) => {
      if (pass.enabled && currentTexture) {
        pass.material.uniforms.tDiffuse.value = currentTexture;
        pass.material.uniforms.u_time.value = time;

        this.renderer.setRenderTarget(pass.renderTarget);
        this.renderer.render(pass.scene, pass.camera);
        currentTexture = pass.renderTarget.texture;
      }
    });

    // Final pass to screen
    this.renderer.setRenderTarget(null);
    this.finalMaterial.uniforms.tDiffuse.value = currentTexture;
    this.finalMaterial.uniforms.tOriginal.value = this.exportTexture || this.videoTexture;
    this.renderer.render(this.finalScene, this.camera);
  }

  animate = () => {
    requestAnimationFrame(this.animate);

    if (this.isExporting) return;

    if (this.mediaElement) {
      if (this.isVideo) {
        // If we are reading automation and not actively clicking/overdubbing
        // For now, interpolate everything
        const time = (this.mediaElement as HTMLVideoElement).currentTime;
        this.applyAutomation(time);
        this.renderPasses(time);
      } else {
        // Evaluate at time 0 for images
        this.applyAutomation(0);
        this.renderPasses(performance.now() / 1000);
      }
    }
  }
}

export let engine: ThreeRenderer | null = null;
export const initEngine = (canvas: HTMLCanvasElement) => {
  engine = new ThreeRenderer(canvas);
  return engine;
};

import { EffectTheme } from './themes';

export interface ParameterDefinition {
  id: string;
  name: string;
  type: "float" | "boolean" | "color";
