// === Shader Library ===

// Vert shader is common: pass-through
export const defaultVertexShader = `
varying vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}
`;

const analogFilmShader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform vec2 u_resolution;
uniform float stock;
uniform float contrast;
uniform float fade;
uniform float saturation;
uniform float grain;
uniform float uFilmLabEnabled;
uniform float uStockSelect;
varying vec2 vUv;

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float getFilmLightness(vec3 c) {
    return dot(c, vec3(0.299, 0.587, 0.114));
}

vec3 applyStock(vec3 color, float s) {
    if (s < 0.) return color;

    vec3 s0 = vec3(color.r * 1.08, color.g * 0.98, color.b * 0.92);
    vec3 s1 = vec3(color.r * 0.95, color.g * 1.04, color.b * 1.06);
    vec3 s2 = vec3(color.r * 0.95 + 0.05, color.g * 0.95 + 0.05, color.b * 0.90 + 0.08);
    vec3 s3 = vec3(color.r * 1.05, color.g * 0.90, color.b * 0.75);
    vec3 s4 = vec3(color.r * 1.02, color.g * 1.02, color.b * 1.05);
    vec3 s5 = vec3(color.r * 1.10, color.g * 0.92 + 0.04, color.b * 1.08);

    vec3 a = mix(s0, s1, smoothstep(0.0, 0.2, s));
    vec3 b = mix(a,  s2, smoothstep(0.2, 0.4, s));
    vec3 c = mix(b,  s3, smoothstep(0.4, 0.6, s));
    vec3 d = mix(c,  s4, smoothstep(0.6, 0.8, s));
    vec3 e = mix(d,  s5, smoothstep(0.8, 1.0, s));
    return e;
}

vec3 sCurve(vec3 x, float c) {
    x = (x - 0.5) * (1.0 + c * 0.8) + 0.5;
    x = clamp(x, 0.0, 1.0);
    x = x * x * (3.0 - 2.0 * x);
    return x;
}

void main() {
    vec2 uv = vUv;

    vec3 color = texture2D(tDiffuse, uv).rgb;
    color = applyStock(color, stock);

    if (uFilmLabEnabled > 0.5) {
        if (uStockSelect >= 0.5 && uStockSelect < 1.5) color = mix(color, color * vec3(1.2, 0.9, 1.1), 0.5); // Sakura2
        else if (uStockSelect >= 1.5 && uStockSelect < 2.5) color = mix(color, color * vec3(0.8, 1.0, 1.4), 0.5); // Aoi
        else if (uStockSelect >= 2.5 && uStockSelect < 3.5) color = mix(color, color * vec3(0.9, 1.3, 0.8), 0.5); // Mori
        else if (uStockSelect >= 3.5 && uStockSelect < 4.5) color = mix(color, color * vec3(0.7, 0.6, 1.3), 0.5); // Yoru
        else if (uStockSelect >= 4.5 && uStockSelect < 5.5) color = mix(color, color * vec3(1.1 * 0.8, 1.1 * 0.8, 1.1 * 0.8), 0.5); // Kumo
        else if (uStockSelect >= 5.5 && uStockSelect < 6.5) color = mix(color, color * vec3(1.3, 1.2, 0.9), 0.5); // Kaze
        else if (uStockSelect >= 6.5 && uStockSelect < 7.5) color = mix(color, color * vec3(0.7, 0.85, 1.1), 0.7); // Yugen (Cold/Dark)
    }

    color = sCurve(color, contrast);
    // Matte film lift: lift blacks more than highlights
    color = mix(color, vec3(1.0), fade * 0.5 * pow(clamp(1.0 - color, 0.0, 1.0), vec3(2.0)));

    float lum = getFilmLightness(color);
    vec3 gray = vec3(lum);
    color = mix(gray, color, saturation);
    float highlight = smoothstep(0.6, 1.0, lum);
    color = mix(color, vec3(lum), highlight * 0.4);

    if (grain > 0.0) {
        float grainNoise = fract(sin(dot(uv + fract(floor(u_time * 24.0) / 24.), vec2(12.9898, 78.233))) * 43758.5453);
        color += (grainNoise - 0.5) * grain * 0.1;
    }

    color = clamp(color, 0.0, 1.0);
    gl_FragColor = vec4(color, 1.0);
}
`;

const duotoneShader = `
uniform sampler2D tDiffuse;
uniform vec3 shadow_color;
uniform vec3 highlight_color;
uniform float balance;
uniform float smoothness;
varying vec2 vUv;

void main() {
    vec3 color = texture2D(tDiffuse, vUv).rgb;

    // Luminance
    float lum = dot(color, vec3(0.299, 0.587, 0.114));

    // Smooth duotone blend
    float t = smoothstep(balance - smoothness, balance + smoothness, lum);
    color = mix(shadow_color, highlight_color, t);

    gl_FragColor = vec4(color, 1.0);
}
`;

const retroShader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform vec2 u_resolution;
uniform float chroma;
uniform float barrel_distortion;
uniform float color_quantization;
uniform float pixel_size;
varying vec2 vUv;

vec2 computeBarrelDistortion(vec2 coord, float amt) {
    vec2 cc = coord - 0.5;
    float dist = dot(cc, cc);
    return coord + cc * dist * amt;
}

void main() {
    vec2 uv = vUv;

    // Pixelation
    if (pixel_size > 1.0) {
        vec2 gridSize = u_resolution / pixel_size;
        uv = floor(uv * gridSize) / gridSize;
    }

    // Barrel distortion
    if (barrel_distortion > 0.0) {
        uv = computeBarrelDistortion(uv, barrel_distortion);
    }

    // If UV is outside, render black
    if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) {
        gl_FragColor = vec4(0.0, 0.0, 0.0, 1.0);
        return;
    }

    // Chromatic Aberration
    float r = texture2D(tDiffuse, uv + vec2(chroma, 0.0)).r;
    float g = texture2D(tDiffuse, uv).g;
    float b = texture2D(tDiffuse, uv - vec2(chroma, 0.0)).b;

    vec3 color = vec3(r, g, b);

    // Color Quantization
    if (color_quantization >= 1.0) {
        color = floor(color * color_quantization) / color_quantization;
    }

    gl_FragColor = vec4(color, 1.0);
}
`;

const chronoShader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform float strips;
uniform float shift;
varying vec2 vUv;

void main() {
    float n = max(floor(strips), 2.0);
    float strip = floor(vUv.x * n);
    float offset = sin(strip + u_time * shift) * 0.02;
    vec2 suv = vUv + vec2(offset, 0.0);
    vec3 color = texture2D(tDiffuse, suv).rgb;
    gl_FragColor = vec4(color, 1.0);
}
`;

const halationShader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform vec2 u_resolution;
uniform float threshold;
uniform float radius;
uniform float intensity;
uniform float warmth;
varying vec2 vUv;

void main() {
    vec2 uv = vUv;
    vec3 color = texture2D(tDiffuse, uv).rgb;
    vec2 texel = vec2(radius) / u_resolution;

    vec3 bloom = vec3(0.0);
    float weight = 0.0;

    // 8-sample cross and diagonal blur
    vec3 s1 = texture2D(tDiffuse, uv + vec2(-texel.x, 0.0)).rgb;
    vec3 s2 = texture2D(tDiffuse, uv + vec2( texel.x, 0.0)).rgb;
    vec3 s3 = texture2D(tDiffuse, uv + vec2(0.0, -texel.y)).rgb;
    vec3 s4 = texture2D(tDiffuse, uv + vec2(0.0,  texel.y)).rgb;
    vec3 s5 = texture2D(tDiffuse, uv + vec2(-texel.x, -texel.y) * 0.7).rgb;
    vec3 s6 = texture2D(tDiffuse, uv + vec2( texel.x,  texel.y) * 0.7).rgb;
    vec3 s7 = texture2D(tDiffuse, uv + vec2(-texel.x,  texel.y) * 0.7).rgb;
    vec3 s8 = texture2D(tDiffuse, uv + vec2( texel.x, -texel.y) * 0.7).rgb;

    float b1 = dot(s1, vec3(0.299, 0.587, 0.114));
    float b2 = dot(s2, vec3(0.299, 0.587, 0.114));
    float b3 = dot(s3, vec3(0.299, 0.587, 0.114));
    float b4 = dot(s4, vec3(0.299, 0.587, 0.114));
    float b5 = dot(s5, vec3(0.299, 0.587, 0.114));
    float b6 = dot(s6, vec3(0.299, 0.587, 0.114));
    float b7 = dot(s7, vec3(0.299, 0.587, 0.114));
    float b8 = dot(s8, vec3(0.299, 0.587, 0.114));

    float t1 = smoothstep(threshold - 0.05, threshold + 0.05, b1);
    float t2 = smoothstep(threshold - 0.05, threshold + 0.05, b2);
    float t3 = smoothstep(threshold - 0.05, threshold + 0.05, b3);
    float t4 = smoothstep(threshold - 0.05, threshold + 0.05, b4);
    float t5 = smoothstep(threshold - 0.05, threshold + 0.05, b5);
    float t6 = smoothstep(threshold - 0.05, threshold + 0.05, b6);
    float t7 = smoothstep(threshold - 0.05, threshold + 0.05, b7);
    float t8 = smoothstep(threshold - 0.05, threshold + 0.05, b8);

    bloom += s1 * t1; weight += t1;
    bloom += s2 * t2; weight += t2;
    bloom += s3 * t3; weight += t3;
    bloom += s4 * t4; weight += t4;
    bloom += s5 * t5; weight += t5;
    bloom += s6 * t6; weight += t6;
    bloom += s7 * t7; weight += t7;
    bloom += s8 * t8; weight += t8;

    if (weight > 0.0) bloom /= weight;

    // Warm reddish-orange tint characteristic of halation
    vec3 warmTint = mix(vec3(1.0), vec3(1.0, 0.35, 0.2), warmth);
    bloom *= warmTint;

    color += bloom * intensity;

    gl_FragColor = vec4(color, 1.0);
}
`;

const longExposureShader = `
uniform sampler2D tDiffuse;
uniform vec2 u_resolution;
uniform float shutter;
uniform float direction;
uniform float useKey;
uniform vec3 keyColor;
uniform float keyThreshold;
uniform float keyTolerance;
uniform float useLumaKey;
uniform float lumaThreshold;
uniform float lumaTolerance;
uniform float invertLuma;
varying vec2 vUv;

void main() {
    vec2 uv = vUv;
    vec3 clean = texture2D(tDiffuse, uv).rgb;

    float colorMask = 1.0;
    if (useKey > 0.5) {
        // Color key
        float dist = length(clean - keyColor);
        colorMask = 1.0 - smoothstep(keyThreshold - keyTolerance, keyThreshold + keyTolerance, dist);
    }

    float lumaMask = 1.0;
    if (useLumaKey > 0.5) {
        float lum = dot(clean, vec3(0.299, 0.587, 0.114));
        lumaMask = smoothstep(lumaThreshold - lumaTolerance, lumaThreshold + lumaTolerance, lum);
        if (invertLuma > 0.5) {
            lumaMask = 1.0 - lumaMask;
        }
    }

    float mask = colorMask * lumaMask;

    if (mask < 0.05) {
        gl_FragColor = vec4(clean, 1.0);
        return;
    }

    float angle = direction * 6.28318530718;
    vec2 dir = vec2(cos(angle), sin(angle));
    vec2 step = dir / u_resolution * shutter * 0.2;
    vec3 color = vec3(0.0);
    float weight = 0.0;
    for (int i = 0; i < 20; i++) {
        float fi = float(i);
        float w = exp(-fi * 0.08 * 1.0);
        color += texture2D(tDiffuse, uv + step * fi).rgb * w;
        weight += w;
    }
    color /= weight;

    color = mix(clean, color, mask);
    gl_FragColor = vec4(color, 1.0);
}
`;

const bloomShader = `
uniform sampler2D tDiffuse;
uniform vec2 u_resolution;
uniform float threshold;
uniform float radius;
uniform float intensity;
varying vec2 vUv;

void main() {
    vec2 uv = vUv;
    vec2 texel = 1.0 / u_resolution;
    vec3 color = texture2D(tDiffuse, uv).rgb;

    // Extract bright pixels
    float lum = dot(color, vec3(0.299, 0.587, 0.114));
    float brightMask = smoothstep(threshold, threshold + 0.15, lum);

    // Multi-directional Gaussian blur approximation (ping-pong without FBOs)
    vec3 bloom = vec3(0.0);
    float totalWeight = 0.0;
    float r = max(radius, 1.0);
    float iters = max(floor(4.0), 2.0);
    float q = 1.0;

    for (float d = 0.0; d < 6.28318; d += 0.785398) {
        vec2 dir = vec2(cos(d), sin(d));
        for (float i = 1.0; i <= 8.0; i++) {
            if (i > iters) break;
            float fi = i * q;
            vec2 off = dir * texel * fi * r;
            float w = exp(-fi * fi * 0.15);
            vec3 s = texture2D(tDiffuse, uv + off).rgb;
            float sl = dot(s, vec3(0.299, 0.587, 0.114));
            float sb = smoothstep(threshold, threshold + 0.2, sl);
            bloom += s * w * sb;
            totalWeight += w;
        }
    }

    if (totalWeight > 0.0) {
        bloom /= totalWeight;
    }

    // Additive blend
    color += bloom * intensity;
    color = clamp(color, 0.0, 1.0);
    gl_FragColor = vec4(color, 1.0);
}
`;

const pikusoriShader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform vec2 u_resolution;
uniform float uPixelSortIntensity;
uniform float uDepthGlitchIntensity;
uniform float uTearingIntensity;
uniform float uSignalJitter;

uniform float u_useDepth;
uniform float u_invertDepth;
uniform float u_depthTolerance;
uniform float u_depthThreshold;

uniform float u_useLuma;
uniform float u_invertLuma;
uniform float u_lumaTolerance;
uniform float u_lumaThreshold;

varying vec2 vUv;

float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

float noise(vec2 uv) {
    return fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453);
}

// Approximate depth: edge magnitude + local contrast + vertical position
float depthProxy(vec2 uv, vec2 texel) {
    vec3 c = texture2D(tDiffuse, uv).rgb;
    vec3 l = texture2D(tDiffuse, uv + vec2(-texel.x, 0.0)).rgb;
    vec3 r = texture2D(tDiffuse, uv + vec2( texel.x, 0.0)).rgb;
    vec3 t = texture2D(tDiffuse, uv + vec2(0.0, -texel.y)).rgb;
    vec3 b = texture2D(tDiffuse, uv + vec2(0.0,  texel.y)).rgb;

    float edgeH = length(c - l) + length(c - r);
    float edgeV = length(c - t) + length(c - b);
    float edge = (edgeH + edgeV) * 0.5;

    float localVar = (length(c - l) + length(c - r) + length(c - t) + length(c - b)) * 0.25;

    // Vertical bias: lower in frame = closer (ground plane heuristic)
    float vertBias = 1.0 - uv.y;

    // Combine cues
    float depth = edge * 2.0 + localVar * 1.5 + vertBias * 0.3;
    return smoothstep(0.0, 1.0, depth);
}

void main() {
    float iTime = u_time;
    vec2 uv = vUv;
    vec2 texel = 1.0 / u_resolution;

    // Depth mask
    float depth = depthProxy(uv, texel);
    float depthMask = 1.0;
    if (u_useDepth > 0.5) {
        depthMask = smoothstep(u_depthThreshold - u_depthTolerance, u_depthThreshold + u_depthTolerance, depth);
        if (u_invertDepth > 0.5) {
            depthMask = 1.0 - depthMask;
        }
    }

    vec3 clean = texture2D(tDiffuse, uv).rgb;

    // Luma mask
    float lum = dot(clean, vec3(0.299, 0.587, 0.114));
    float lumaMask = 1.0;
    if (u_useLuma > 0.5) {
        lumaMask = smoothstep(u_lumaThreshold - u_lumaTolerance, u_lumaThreshold + u_lumaTolerance, lum);
        if (u_invertLuma > 0.5) {
            lumaMask = 1.0 - lumaMask;
        }
    }

    float combinedMask = depthMask * lumaMask;

    if ((u_useDepth > 0.5 || u_useLuma > 0.5) && combinedMask < 0.05) {
        gl_FragColor = vec4(clean, 1.0);
        return;
    }

    vec3 color = clean;

    // Jitter
    if (uSignalJitter > 0.01) {
        float jitter = (noise(vec2(iTime * 10.0, uv.y)) - 0.5) * uSignalJitter * 0.05;
        uv.x += jitter;
        // Horizontal tearing
        if (noise(vec2(iTime, uv.y * 10.0)) > 1.0 - uSignalJitter * 0.1) {
           uv.x += (noise(vec2(iTime)) - 0.5) * 0.1;
        }
    }

    // Depth Glitch Effect
    if (uDepthGlitchIntensity > 0.01) {
        float g2_seed = floor(iTime * 15.0);
        float g2_noise = noise(vec2(uv.y * 30.0, g2_seed));
        if (g2_noise > 0.9) {
            float g2_shift = (noise(vec2(g2_seed)) - 0.5) * uDepthGlitchIntensity * 0.15;
            uv.x += g2_shift;
        }
    }

    // Tearing
    if (uTearingIntensity > 0.01) {
        float tearY = uv.y * 4.0 + iTime;
        float tear = clamp(cos(tearY) * 2.0 - 1.5, 0.0, 1.0) * uTearingIntensity;
        uv.x += tear * 0.05 * noise(vec2(iTime, uv.y));
    }

    // Read texture again with modified uv
    uv = fract(uv);
    color = texture2D(tDiffuse, uv).rgb;

    // Pixel sorting
    if (uPixelSortIntensity > 0.01) {
        float ps_column = floor(uv.x * 250.0);
        float ps_offset = uPixelSortIntensity * noise(vec2(ps_column, iTime * 0.05)) * lumaMask * 2.0;
        vec2 ps_uv = vec2(uv.x, uv.y - ps_offset);
        color = texture2D(tDiffuse, fract(ps_uv)).rgb;
    }

    // Mix based on mask
    color = mix(clean, color, combinedMask);

    gl_FragColor = vec4(color, 1.0);
}
`;

const glitch2Shader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform vec2 u_resolution;
uniform float chroma;
uniform float blockSize;
uniform float speed;
uniform float intensity;
uniform float u_useDepth;
uniform float u_invertDepth;
uniform float u_depthTolerance;
uniform float u_depthThreshold;
uniform float u_useLuma;
uniform float u_invertLuma;
uniform float u_lumaTolerance;
uniform float u_lumaThreshold;
varying vec2 vUv;

float hash(float n) {
    return fract(sin(n) * 43758.5453123);
}

// Approximate depth: edge magnitude + local contrast + vertical position
float depthProxy(vec2 uv, vec2 texel) {
    vec3 c = texture2D(tDiffuse, uv).rgb;
    vec3 l = texture2D(tDiffuse, uv + vec2(-texel.x, 0.0)).rgb;
    vec3 r = texture2D(tDiffuse, uv + vec2( texel.x, 0.0)).rgb;
    vec3 t = texture2D(tDiffuse, uv + vec2(0.0, -texel.y)).rgb;
    vec3 b = texture2D(tDiffuse, uv + vec2(0.0,  texel.y)).rgb;

    float edgeH = length(c - l) + length(c - r);
    float edgeV = length(c - t) + length(c - b);
    float edge = (edgeH + edgeV) * 0.5;

    float localVar = (length(c - l) + length(c - r) + length(c - t) + length(c - b)) * 0.25;

    // Vertical bias: lower in frame = closer (ground plane heuristic)
    float vertBias = 1.0 - uv.y;

    // Combine cues
    float depth = edge * 2.0 + localVar * 1.5 + vertBias * 0.3;
    return smoothstep(0.0, 1.0, depth);
}

void main() {
    vec2 uv = vUv;
    vec2 texel = 1.0 / u_resolution;
    float depth = depthProxy(uv, texel);

    vec3 clean = texture2D(tDiffuse, uv).rgb;

    float depthMask = 1.0;
    if (u_useDepth > 0.5) {
        depthMask = smoothstep(u_depthThreshold - u_depthTolerance, u_depthThreshold + u_depthTolerance, depth);
        if (u_invertDepth > 0.5) {
            depthMask = 1.0 - depthMask;
        }
    }

    // Luma mask
    float lum = dot(clean, vec3(0.299, 0.587, 0.114));
    float lumaMask = 1.0;
    if (u_useLuma > 0.5) {
        lumaMask = smoothstep(u_lumaThreshold - u_lumaTolerance, u_lumaThreshold + u_lumaTolerance, lum);
        if (u_invertLuma > 0.5) {
            lumaMask = 1.0 - lumaMask;
        }
    }

    float combinedMask = depthMask * lumaMask;

    // Early out for background if masked completely
    if ((u_useDepth > 0.5 || u_useLuma > 0.5) && combinedMask < 0.05) {
        gl_FragColor = vec4(clean, 1.0);
        return;
    }

    float blockTime = floor(u_time * speed * 8.0);
    float row = floor(uv.y / max(blockSize * 0.001, 0.001));

    float h1 = hash(row + blockTime);
    float h2 = hash(row * 7.31 + blockTime * 13.0);
    float h3 = hash(row * 17.91 + blockTime * 3.7);
    float h4 = hash(row * 31.13 + blockTime * 19.0);
    float h5 = hash(row * 41.07 + blockTime * 13.0);

    // Scale glitch probability by the mask
    float prob = smoothstep(0.15, 0.8, combinedMask);

    float shift = 0.0;
    if (h1 > (1.0 - prob * intensity * 0.4)) {
        shift = (h2 - 0.5) * intensity * 0.25;
    }
    if (h3 > (1.0 - prob * intensity * 0.2)) {
        shift += (h1 - 0.5) * intensity * 0.5;
    }

    vec2 glitchUV = uv;
    glitchUV.x += shift;
    glitchUV.x = fract(glitchUV.x + 1.0);

    float chromaShift = chroma * (1.0 + abs(shift) * 20.0);
    float r = texture2D(tDiffuse, glitchUV + vec2(chromaShift, 0.0)).r;
    float g = texture2D(tDiffuse, glitchUV).g;
    float b = texture2D(tDiffuse, glitchUV - vec2(chromaShift, 0.0)).b;
    vec3 color = vec3(r, g, b);

    if (h4 > (1.0 - intensity * 0.4 * prob) && h1 < 0.4) {
        float sourceRow = hash(row * 5.0 + blockTime * 11.0);
        vec2 sourceUV = vec2(uv.x, sourceRow);
        vec3 replace = texture2D(tDiffuse, sourceUV).rgb;
        color = mix(color, replace, 0.85);
    }

    if (h2 > (1.0 - intensity * 0.15 * prob) && h3 > 0.5) {
        color = mix(color, vec3(0.0), 0.7);
    }

    if (h3 > (1.0 - intensity * 0.1 * prob) && h4 < 0.3) {
        color = mix(color, 1.0 - color, 0.5);
    }

    // Inverted band
    if (h5 > (1.0 - intensity * 0.1 * prob)) {
        color = 1.0 - color;
    }

    float sl = 0.85 + 0.15 * sin(uv.y * u_resolution.y * 1.2);
    color *= mix(1.0, sl, 0.5);

    float streak = step(0.97, hash(floor(uv.y * u_resolution.y * 0.3) + blockTime * 37.0));
    color += streak * 0.08;

    // Blend glitched result by mask so background stays clean
    color = mix(clean, color, prob);

    gl_FragColor = vec4(color, 1.0);
}
`;

const liftGammaGainShader = `
uniform sampler2D tDiffuse;
varying vec2 vUv;

uniform float lift;
uniform vec3 liftColor;
uniform float gamma;
uniform vec3 gammaColor;
uniform float gain;
uniform vec3 gainColor;
uniform float vignette;

void main() {
    vec3 color = texture2D(tDiffuse, vUv).rgb;

    // Resolve-style Lift Gamma Gain
    // Lift: offsets blacks, anchored at 1.0 (white point stays fixed)
    vec3 totalLift = liftColor + vec3(lift);
    color = color * (1.0 - totalLift) + totalLift;

    // Gain: white point adjustment (black point stays fixed at 0.0)
    vec3 totalGain = gainColor * gain;
    color *= totalGain;

    // Gamma: midtone power curve
    vec3 totalGamma = gammaColor * gamma;
    color = pow(max(color, vec3(0.0)), 1.0 / max(totalGamma, vec3(0.01)));

    float dist = distance(vUv, vec2(0.5));
    float v = 1.0 - (smoothstep(0.3, 0.7, dist) * vignette);
    color *= v;

    color = clamp(color, 0.0, 1.0);
    gl_FragColor = vec4(color, 1.0);
}
`;

const hsvShader = `
uniform sampler2D tDiffuse;
varying vec2 vUv;

uniform float zoneCenter;
uniform float hueShift;
uniform float satShift;
uniform float lumShift;
uniform float spread;

vec3 rgb2hsv(vec3 c) {
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));
    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

vec3 hsv2rgb(vec3 c) {
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

float hueDist(float a, float b) {
    float d = abs(a - b);
    return min(d, 1.0 - d);
}

void main() {
    vec3 color = texture2D(tDiffuse, vUv).rgb;
    vec3 hsv = rgb2hsv(color);

    float mapped_spread = mix(.25, 3., 1. - spread);
    float w = exp(-hueDist(hsv.x, zoneCenter) * max(mapped_spread, 0.1) * 20.0);

    hsv.x = fract(hsv.x + hueShift * w);
    hsv.y = clamp(hsv.y * (1.0 + satShift * w), 0.0, 1.0);
    hsv.z = clamp(hsv.z + lumShift * w, 0.0, 1.0);

    color = hsv2rgb(hsv);
    gl_FragColor = vec4(color, 1.0);
}
`;

const crtShader = `
uniform sampler2D tDiffuse;
uniform float u_time;
uniform vec2 u_resolution;

uniform float uCrtIntensity;
uniform float uCircuitIntensity;
uniform float uSignalJitter;
uniform float uScanlineIntensity;

varying vec2 vUv;

float noise(vec2 uv) {
  return fract(sin(dot(uv, vec2(12.9898, 78.233))) * 43758.5453);
}

void main() {
    float iTime = u_time;
    vec2 uv = vUv;

    // Signal jittering
    if (uSignalJitter > 0.01) {
        float jitter = (noise(vec2(iTime * 10.0, uv.y)) - 0.5) * uSignalJitter * 0.05;
        uv.x += jitter;
        // Horizontal tearing
        if (noise(vec2(iTime, uv.y * 10.0)) > 1.0 - uSignalJitter * 0.1) {
            uv.x += (noise(vec2(iTime)) - 0.5) * 0.1;
        }
        uv.x = clamp(uv.x, 0.0, 1.0);
    }

    vec3 color = texture2D(tDiffuse, uv).rgb;

    // Circuit bending
    if (uCircuitIntensity > 0.01) {
        float c_noise = noise(uv * 10.0 + iTime);
        if (c_noise > 0.98 - uCircuitIntensity * 0.1) {
            color += vec3(fract(iTime), fract(iTime * 1.5), fract(iTime * 2.0)) * uCircuitIntensity;
        }
    }

    // Scanlines
    if (uScanlineIntensity > 0.01) {
        color *= 1.0 - (uScanlineIntensity * (0.5 + 0.5 * sin(150. * uv.y * 3.14159 * 2.0)));
    }

    // CRT phosphor
    if (uCrtIntensity > 0.01) {
        vec2 fragCoord = uv * u_resolution;
        vec2 grid_uv = fragCoord.xy * 0.5;
        vec3 phosphor = vec3(0.0);
        if (mod(grid_uv.x, 3.0) < 1.0) phosphor.r = 1.0;
        else if (mod(grid_uv.x, 3.0) < 2.0) phosphor.g = 1.0;
        else phosphor.b = 1.0;
        color *= mix(vec3(1.0), phosphor, uCrtIntensity);
    }

    gl_FragColor = vec4(color, 1.0);
}
`;

const chromaSmearShader = `
uniform sampler2D tDiffuse;
varying vec2 vUv;

uniform float uChromaSmear;
uniform float uChromaHue;
uniform float uChromaStrength;

vec3 rgb2yiq(vec3 c) {
  return vec3(
    dot(c, vec3(0.299, 0.587, 0.114)),
    dot(c, vec3(0.596, -0.274, -0.322)),
    dot(c, vec3(0.211, -0.523, 0.312))
  );
}

vec3 yiq2rgb(vec3 c) {
  return vec3(
    dot(c, vec3(1.0, 0.956, 0.621)),
    dot(c, vec3(1.0, -0.272, -0.647)),
    dot(c, vec3(1.0, -1.106, 1.703))
  );
}

void main() {
    vec3 origColor = texture2D(tDiffuse, vUv).rgb;
    vec3 orig_yiq = rgb2yiq(origColor);
    vec3 yiq = orig_yiq;

    // Smear I and Q channels horizontally
    float iSmear = 0.0;
    float qSmear = 0.0;
    float base_off = uChromaSmear * 0.01;

    for(int i=0; i<8; i++) {
        float fi = float(i);
        vec2 offset = vec2(fi * base_off * 1.5, 0.0);
        iSmear += rgb2yiq(texture2D(tDiffuse, vUv - offset).rgb).y;
        qSmear += rgb2yiq(texture2D(tDiffuse, vUv - offset * 0.6).rgb).z;
    }

    float iFinal = iSmear / 8.0;
    float qFinal = qSmear / 8.0;

    // YIQ Color Phase Rotation (Hue Shift)
    float angle = uChromaHue * 6.28318;
    float cosA = cos(angle);
    float sinA = sin(angle);
    float iRot = iFinal * cosA - qFinal * sinA;
    float qRot = iFinal * sinA + qFinal * cosA;

    // Blend Strength
    yiq.y = mix(orig_yiq.y, iRot, uChromaStrength);
    yiq.z = mix(orig_yiq.z, qRot, uChromaStrength);

    vec3 color = yiq2rgb(yiq);
    gl_FragColor = vec4(color, 1.0);
}
`;

